// Node 2: Normalize incoming Wazuh alert into a flat, predictable object.
// Handles both Windows (data.win.system) and Linux/SYSLOG alert structures.

const raw = $input.first().json;

// --- Field Extraction with safe fallbacks ---
const hostName =
  raw?.data?.win?.system?.computer ||
  raw?.agent?.name ||
  raw?.data?.srcip ||   // fallback for network device alerts
  'UNKNOWN_HOST';

const agentId   = raw?.agent?.id     || '000';
const ruleId    = raw?.rule?.id      || '0';
const ruleLevel = parseInt(raw?.rule?.level || '0', 10);
const ruleDesc  = raw?.rule?.description || 'No description';

// Source IP — check multiple common locations
const srcIp =
  raw?.data?.win?.eventdata?.ipAddress ||
  raw?.data?.srcip ||
  raw?.data?.src_ip ||
  raw?.network?.sourceIp ||
  null;

// Destination IP
const dstIp =
  raw?.data?.win?.eventdata?.ipport?.split(':')[0] ||
  raw?.data?.dstip ||
  null;

// MITRE ATT&CK mapping (present in Wazuh 4.x+)
const mitreTechnique = raw?.rule?.mitre?.technique?.[0] || null;
const mitreTactic    = raw?.rule?.mitre?.tactic?.[0]    || null;

const alertId    = raw?.id || `manual-${Date.now()}`;
const alertTime  = raw?.timestamp || new Date().toISOString();
const fullGroups = raw?.rule?.groups || [];

return [{
  json: {
    // Pass raw alert through for LLM context
    rawAlert: raw,
    // Normalized fields for downstream logic
    normalized: {
      alertId,
      alertTime,
      hostName,
      agentId,
      ruleId,
      ruleLevel,
      ruleDesc,
      srcIp,
      dstIp,
      mitreTechnique,
      mitreTactic,
      ruleGroups: fullGroups,
      dedupeKey: `${hostName}:${ruleId}`,
    }
  }
}];

// Node 3: Stage 1 — Stateful Deduplication Cache
// Uses n8n workflow static data as a persistent TTL cache.

// 1. Corrected n8n syntax for static data
const staticData = $getWorkflowStaticData('global');
const input      = $input.first().json;

// 2. Safety check: 'normalized' is not in the provided input JSON. 
// Adding an empty object fallback to prevent a new TypeError.
const normalized = input.normalized || {};
const dedupeKey  = normalized.dedupeKey || input.body?.rule?.id || 'default_key';

const WINDOW_MS  = 15 * 60 * 1000;  // 15-minute suppression window
const now        = Date.now();

// Initialize the cache namespace if first run
if (!staticData.dedupeCache) {
  staticData.dedupeCache = {};
}

// ── Garbage collect stale keys (run on every alert to prevent memory growth) ──
const keysToDelete = [];
for (const [key, ts] of Object.entries(staticData.dedupeCache)) {
  if ((now - ts) > WINDOW_MS * 2) {  // double window for safety margin
    keysToDelete.push(key);
  }
}
keysToDelete.forEach(k => delete staticData.dedupeCache[k]);

// ── Deduplication check ──
const lastSeen   = staticData.dedupeCache[dedupeKey];
const isDuplicate = !!(lastSeen && (now - lastSeen) < WINDOW_MS);
const minutesAgo  = lastSeen ? Math.round((now - lastSeen) / 60000) : null;

if (!isDuplicate) {
  // First occurrence in window — record it
  staticData.dedupeCache[dedupeKey] = now;
}

return [{
  json: {
    ...input,
    dedup: {
      isDuplicate,
      dedupeKey,
      lastSeenMinutesAgo: minutesAgo,
      cacheSize: Object.keys(staticData.dedupeCache).length,
    }
  }
}];

// Extract credentials from Vault KV v2 response
const vaultResponse = $input.first().json;

// 1. Fix the Node Reference
// Replace 'Deduplication Cache' with the EXACT name of the node you are trying to pull from.
const prevData = $('Deduplication Cache').first().json; 

// 2. Fix the JSON Path
// Based on your input, the KV pairs are directly under .data, not .data.data
const indexerCreds = vaultResponse.data; 

return [{
  json: {
    ...prevData,
    vault: {
      indexer: {
        url:      indexerCreds.url,
        username: indexerCreds.username,
        password: indexerCreds.password,
        // Pre-compute Basic auth header
        basicAuth: 'Basic ' + Buffer.from(`${indexerCreds.username}:${indexerCreds.password}`).toString('base64'),
      }
    }
  }
}];

// Node 7: Parse the OpenSearch aggregation response into a clean context object.

const osResponse = $input.first().json;

// 1. Fixed Node Reference: Ensure this perfectly matches your canvas node name!
const prevData   = $('Parse Vault Response').first().json; 

const aggs = osResponse.aggregations;

// Extract alert count
const totalAlerts = aggs?.total_alert_count?.value || 0;

// Build severity distribution map: { "5": 12, "7": 3, "10": 1 }
const severityDist = {};
(aggs?.by_rule_level?.buckets || []).forEach(b => {
  severityDist[`level_${b.key}`] = b.doc_count;
});

// Build top rules list: [{ rule_id: "...", count: N, description: "..." }]
const topRules = (aggs?.top_triggered_rules?.buckets || []).map(b => ({
  ruleId:      b.key,
  count:       b.doc_count,
  description: b.rule_desc?.buckets?.[0]?.key || 'N/A',
}));

// Unique source IPs seen attacking this host in the window
const uniqueSrcIps = aggs?.unique_source_ips?.value || 0;

// Max severity seen in the window
const maxSeverity = aggs?.max_severity?.value || 0;

// Compute a simple activity score for the LLM context
// High volume + high max severity = clearly anomalous baseline
const activityScore = Math.min(100, Math.round(
  (totalAlerts * 0.5) + (maxSeverity * 3) + (uniqueSrcIps * 2)
));

// 2. Safe Fallback for hostName
// We saw earlier that 'normalized' might not exist in the raw alert payload.
const hostName = prevData.normalized?.hostName || 'UNKNOWN_HOST';

return [{
  json: {
    ...prevData,
    enrichment: {
      windowMinutes:    240, // Updated to 4 hours to match the OpenSearch query
      totalAlerts,
      severityDistribution: severityDist,
      topRules,
      uniqueSourceIPs:  uniqueSrcIps,
      maxSeverityInWindow: maxSeverity,
      activityScore,
      // Pre-format a human-readable summary for the LLM prompt
      contextSummary: `In the last 4 hours, host "${hostName}" generated ` +
        `${totalAlerts} total alerts (max severity: ${maxSeverity}). ` +
        `Top triggered rules: ${topRules.map(r => `[${r.ruleId}] ${r.description} (×${r.count})`).join('; ')}. ` +
        `Unique attacking IPs: ${uniqueSrcIps}. Activity score: ${activityScore}/100.`
    }
  }
}];

const vaultData = $('HashiCorp Vault1').first().json.data;
const user = vaultData.username;
const pass = vaultData.password;

// Code nodes are allowed to use Buffer!
const encodedCreds = Buffer.from(`${user}:${pass}`).toString('base64');

return [{
  json: {
    wazuhApiUrl: vaultData.url,
    authHeader: `Basic ${encodedCreds}`
  }
}];

const authResponse = $input.first().json;
const jwtToken     = authResponse.data.token;

if (!jwtToken) {
  throw new Error(`Wazuh API authentication failed: ${JSON.stringify(authResponse)}`);
}

// Pulling the alert context from your enrichment node
const enrichedData = $('Parse Enrichment Response').first().json;

// Pulling the Wazuh manager URL from your second Vault node
const vaultData = $('HashiCorp Vault1').first().json;

return [{
  json: {
    ...enrichedData,
    wazuh: {
      jwtToken,
      bearerHeader: `Bearer ${jwtToken}`,
      apiUrl: vaultData.data.url,
    }
  }
}];

// Node 9: Assemble the full context package for the LLM prompt.

const data       = $input.first().json;
const normalized = data.normalized;
const enrichment = data.enrichment;
const raw        = data.rawAlert;

// Build a clean, structured context string for the LLM
// Only include fields the LLM needs — avoid token bloat from full raw alert
const alertContext = {
  alert_id:        normalized.alertId,
  timestamp:       normalized.alertTime,
  host:            normalized.hostName,
  agent_id:        normalized.agentId,
  rule_id:         normalized.ruleId,
  rule_level:      normalized.ruleLevel,
  rule_description: normalized.ruleDesc,
  rule_groups:     normalized.ruleGroups,
  source_ip:       normalized.srcIp,
  destination_ip:  normalized.dstIp,
  mitre_technique: normalized.mitreTechnique,
  mitre_tactic:    normalized.mitreTactic,
  // Include relevant raw data fields (truncated)
  raw_event_data: JSON.stringify(raw?.data || {}).substring(0, 1500),
};

const historyContext = {
  window_minutes:         enrichment.windowMinutes,
  total_alerts:           enrichment.totalAlerts,
  max_severity_in_window: enrichment.maxSeverityInWindow,
  severity_distribution:  enrichment.severityDistribution,
  top_triggered_rules:    enrichment.topRules,
  unique_source_ips:      enrichment.uniqueSourceIPs,
  activity_score:         enrichment.activityScore,
};

return [{
  json: {
    ...data,
    llmInput: {
      alertContext,
      historyContext,
      // These are passed directly into the prompt template in Node 10
      alertContextJson:  JSON.stringify(alertContext,  null, 2),
      historyContextJson: JSON.stringify(historyContext, null, 2),
    }
  }
}];

// Node 11: Safely parse the LLM output JSON and enforce schema + fallback behavior.
// Gemini sometimes wraps JSON in markdown fences despite instructions — strip them.

const data      = $input.first().json;
const llmOutput = data.output || data.text || data.response || '';

let parsed;

try {
  // Strip markdown code fences if present (Gemini fallback behavior)
  const cleaned = llmOutput
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/```\s*$/,    '')
    .trim();

  parsed = JSON.parse(cleaned);
} catch (err) {
  // Hard parse failure — log the raw output and default to INVESTIGATE
  console.error('LLM JSON parse failed. Raw output:', llmOutput);
  parsed = {
    reasoning:             `PARSE_ERROR: LLM output was not valid JSON. Raw: ${llmOutput.substring(0, 500)}`,
    risk_score:            50,
    action:                'INVESTIGATE',
    confidence:            'LOW',
    key_indicators:        ['llm_parse_failure'],
    recommended_next_steps: 'Manual review required — AI output could not be parsed.',
  };
}

// ── Schema enforcement & sanitization ──
const validActions = ['IGNORE', 'INVESTIGATE', 'ISOLATE'];

const riskScore = Math.min(100, Math.max(1, parseInt(parsed.risk_score || 50, 10)));
let   action    = (parsed.action || 'INVESTIGATE').toUpperCase();

if (!validActions.includes(action)) {
  action = 'INVESTIGATE'; // Safe default for unexpected action values
}

// Double-check threshold consistency (prevent hallucinated action/score mismatches)
if (action === 'ISOLATE' && riskScore < 75) {
  console.warn(`LLM action/score mismatch: ISOLATE requested with risk_score=${riskScore}. Downgrading to INVESTIGATE.`);
  action = 'INVESTIGATE';
}
if (action === 'IGNORE' && riskScore > 30) {
  console.warn(`LLM action/score mismatch: IGNORE requested with risk_score=${riskScore}. Upgrading to INVESTIGATE.`);
  action = 'INVESTIGATE';
}

return [{
  json: {
    ...data,
    assessment: {
      reasoning:            parsed.reasoning            || 'No reasoning provided.',
      risk_score:           riskScore,
      action,
      confidence:           parsed.confidence           || 'LOW',
      key_indicators:       parsed.key_indicators       || [],
      recommended_next_steps: parsed.recommended_next_steps || '',
      // Metadata for audit log
      llm_raw_output:       llmOutput,
      parse_success:        !!parsed.reasoning,
      evaluated_at:         new Date().toISOString(),
    }
  }
}];

// Node 13a: Log IGNORE decisions for audit trail and respond to webhook.
const data = $input.first().json;
console.log(JSON.stringify({
  event:      'soar_decision',
  action:     'IGNORE',
  host:       data.normalized.hostName,
  rule_id:    data.normalized.ruleId,
  risk_score: data.assessment.risk_score,
  reasoning:  data.assessment.reasoning.substring(0, 200),
  timestamp:  new Date().toISOString(),
}));
// This output feeds the "Respond to Webhook" node
return [{ json: { status: 'suppressed', action: 'IGNORE', ...data.assessment } }];

// SAFETY GATE: Hard-coded rules that MUST pass before any isolation fires.
// This is your last line of defense against self-inflicted DoS.

const data = $input.first().json;

// 1. Safe object chaining: Default to empty objects if missing
const n          = data.normalized || {};
const enrichment = data.enrichment || {};

// 2. Extract values with safe defaults
const hostName    = n.hostName || 'UNKNOWN_HOST';
const agentId     = n.agentId  || 'UNKNOWN_AGENT';
const srcIp       = n.srcIp    || null;
const totalAlerts = enrichment.totalAlerts || 0;

const blocklist = [
  'wazuh.manager', 'wazuh.indexer', 'vault.internal',
  'n8n.internal', 'dc01', 'pdc',  // add your critical infrastructure hostnames
];

const errors = [];

if (blocklist.some(b => hostName.toLowerCase().includes(b))) {
  errors.push(`BLOCKED: Host "${hostName}" is on the infrastructure protection blocklist.`);
}

if (agentId === '000') {
  errors.push(`BLOCKED: Agent ID 000 is the Wazuh Manager itself. Refusing isolation.`);
}

if (!srcIp && totalAlerts < 20) {
  errors.push(`SAFETY: No source IP identified and alert volume < 20. Downgrading to INVESTIGATE.`);
}

if (errors.length > 0) {
  // Override the action — do NOT proceed to isolation
  return [{
    json: {
      ...data,
      isolation_blocked: true,
      isolation_block_reason: errors.join(' | '),
      assessment: { ...(data.assessment || {}), action: 'INVESTIGATE' }
    }
  }];
}

return [{ json: { ...data, isolation_blocked: false } }];

const arResponse = $input.first().json;

// 1. Fixed Node Reference to match your actual n8n canvas
const data = $('Validate Preconditions').first().json;

// 2. Safely check if Wazuh successfully applied the firewall drop
const success = arResponse?.data?.affected_items?.length > 0 ||
                arResponse?.data?.total_affected_items > 0;

// 3. Build the Audit Record (with safe fallbacks)
const auditRecord = {
  event:        'soar_isolation_attempt',
  success,
  host:         data.normalized?.hostName || 'UNKNOWN_HOST',
  agent_id:     data.normalized?.agentId  || 'UNKNOWN_AGENT',
  blocked_ip:   data.normalized?.srcIp    || 'UNKNOWN_IP',
  risk_score:   data.assessment?.risk_score,
  reasoning:    data.assessment?.reasoning?.substring(0, 300) || 'No reasoning',
  ar_response:  JSON.stringify(arResponse || {}).substring(0, 500),
  timestamp:    new Date().toISOString(),
};

console.log(JSON.stringify(auditRecord));

if (!success) {
  throw new Error(`Active Response failed for agent ${auditRecord.agent_id}. Response: ${JSON.stringify(arResponse)}`);
}

return [{ json: { ...data, isolationResult: auditRecord } }];

// Node: Fallback Counter
// Tracks how many times the pipeline fails to route properly within a time window.

const staticData = $getWorkflowStaticData('global');
const data       = $input.first().json;

const now        = Date.now();
const WINDOW_MS  = 60 * 60 * 1000; // 1-hour tracking window
const THRESHOLD  = 3;              // Number of errors before triggering the alert

// 1. Initialize or reset the tracker if the 1-hour window has passed
if (!staticData.fallbackTracker || (now - staticData.fallbackTracker.startTime) > WINDOW_MS) {
  staticData.fallbackTracker = {
    count: 0,
    startTime: now
  };
}

// 2. Increment the error counter
staticData.fallbackTracker.count += 1;
const currentCount = staticData.fallbackTracker.count;

// 3. Check if we have hit the critical threshold
const triggerCriticalAlert = currentCount >= THRESHOLD;

return [{
  json: {
    ...data,
    fallback_metrics: {
      current_error_count: currentCount,
      threshold: THRESHOLD,
      trigger_alert: triggerCriticalAlert,
      window_minutes: 60
    }
  }
}];

// Final Master Audit Log 
const data = $input.first().json;

const masterAuditLog = {
  timestamp: new Date().toISOString(),
  pipeline_status: "COMPLETED",

  // 1. The original alert
  target_host: data.normalized?.hostName || 'Unknown',
  rule_triggered: data.normalized?.ruleDesc || 'Unknown',

  // 2. The historical context
  alerts_in_last_4h: data.enrichment?.totalAlerts || 0,

  // 3. The AI's decision
  ai_action: data.assessment?.action || 'ERROR',
  ai_risk_score: data.assessment?.risk_score || 0,
  ai_reasoning: data.assessment?.reasoning || 'No reasoning captured',

  // 4. Action Results (Only present if it went down these branches)
  active_response_fired: !!data.isolationResult,
  fallback_error_triggered: !!data.fallback_metrics,
};

// Print to the n8n console log (useful for debugging)
console.log("SOAR AUDIT LOG:", JSON.stringify(masterAuditLog));

return [{ json: masterAuditLog }];

const data = $input.first().json;
console.log(JSON.stringify({
  event: 'alert_suppressed_dedup',
  key: data.dedup.dedupeKey,
  last_seen_min_ago: data.dedup.lastSeenMinutesAgo,
  timestamp: new Date().toISOString()
}));
return [{ json: { status: 'suppressed', reason: 'dedup', ...data.dedup } }];
